import 'package:flutter/material.dart';import 'package:modulos/core/theme/app_colors.dart';import 'package:modulos/core/widgets/responsive_layout.dart';import '../controllers/ventas_controller.dart';import '../widgets/venta_form.dart';import '../widgets/venta_table.dart';import '../widgets/venta_actions.dart';class VentasScreen extends StatefulWidget {  final int selectedNav;  final ValueChanged<int> onNavSelect;  const VentasScreen({super.key, required this.selectedNav, required this.onNavSelect});  @override  State<VentasScreen> createState() => _VentasScreenState();}class _VentasScreenState extends State<VentasScreen> {  final _controller = VentasController();  @override  void initState() {    super.initState();    _controller.addListener(() => setState(() {}));    _controller.cargarVentas();  }  @override  void dispose() {    _controller.dispose();    super.dispose();  }  void _abrirFormulario() {    showModalBottomSheet(      context: context,      isScrollControlled: true,      backgroundColor: AppColors.cardBg,      shape: const RoundedRectangleBorder(        borderRadius: BorderRadius.vertical(top: Radius.circular(20)),      ),      builder: (_) => VentaForm(        onSubmit: (venta) async {          await _controller.crearVenta(venta);          if (mounted) {            ScaffoldMessenger.of(context).showSnackBar(              const SnackBar(content: Text('Venta creada')),            );          }        },      ),    );  }  @override  Widget build(BuildContext context) {    return ResponsiveLayout(      selectedNav: widget.selectedNav,      onNavSelect: widget.onNavSelect,      title: 'Ventas',      contentBuilder: (context, constraints) => _buildContent(),    );  }  Widget _buildContent() {    if (_controller.isLoading) {      return const Center(child: CircularProgressIndicator());    }    if (_controller.error != null) {      return Center(        child: Column(          mainAxisAlignment: MainAxisAlignment.center,          children: [            const Icon(Icons.error_outline, size: 48, color: AppColors.negativeRed),            const SizedBox(height: 16),            Text('Error: ${_controller.error}', style: const TextStyle(color: AppColors.textPrimary)),            const SizedBox(height: 16),            ElevatedButton(              onPressed: _controller.cargarVentas,              child: const Text('Reintentar'),              ),          ],        ),      );    }    return Column(      crossAxisAlignment: CrossAxisAlignment.start,      children: [        PageHeader(          title: 'Gestión de Ventas',          count: _controller.ventas.length,          buttonLabel: 'Nueva Venta',          onButtonPressed: () => _abrirFormulario(),        ),        const SizedBox(height: 20),        if (_controller.ventas.isEmpty)          Container(            padding: const EdgeInsets.all(40),            decoration: BoxDecoration(              color: AppColors.cardBg,              borderRadius: BorderRadius.circular(16),              border: Border.all(color: AppColors.cardBorder),            ),            child: const Center(              child: Text('No hay ventas registradas', style: TextStyle(color: AppColors.textSecondary)),            ),          )        else          VentaTable(              ventas: _controller.ventas,              onDelete: (v) => VentaActions.confirmarEliminar(context, v, () async {                try {                  await _controller.eliminarVenta(v.id);                  if (mounted) {                    ScaffoldMessenger.of(context).showSnackBar(const SnackBar(content: Text('Venta eliminada')));                  }                } catch (e) {                  if (mounted) {                    ScaffoldMessenger.of(context).showSnackBar(                      SnackBar(content: Text('Error: $e'), backgroundColor: AppColors.negativeRed),                    );                  }                }              }),            ),      ],    );  }}